"""青蛇果园：python3 snake.py。方向键/WASD 移动，空格暂停，R 重开。
素材采用 CC0 授权，已内嵌。最高分保存在脚本旁的 snake_scores.json。
"""
import json
import math
import random
import time
from pathlib import Path
import tkinter as tk
from tkinter import ttk

ASSET_DATA = {'apple': '', 'skin': ''}

class SnakeGame:
    CELL, COLS, ROWS = 24, 25, 20
    BG = "#FFFFFF"
    SPEEDS = {"悠闲": (190, 95), "标准": (145, 65), "挑战": (105, 45)}

    def __init__(self, root):
        self.root = root
        root.title("贪吃蛇")
        root.resizable(False, False)
        root.configure(bg=self.BG)
        self.score_path = Path(__file__).resolve().with_name("snake_scores.json")
        self.records = self.read_records()
        self.timer = self.frame_timer = None
        self.particles = []
        self.load_textures()
        self.difficulty = tk.StringVar(value="标准")
        self.values = [tk.StringVar() for _ in range(3)]
        header = tk.Frame(root, bg=self.BG)
        header.pack(fill="x", padx=24, pady=(18, 12))
        tk.Label(header, text="青蛇果园", font=("Arial", 24, "bold"),
                 fg="#254b36", bg=self.BG).pack(side="left")
        tk.Label(header, text="S N A K E  /  慢一点，也能吃得更多", font=("Arial", 10),
                 fg="#6b7e70", bg=self.BG).pack(side="right", pady=(12, 0))
        cards = tk.Frame(root, bg=self.BG)
        cards.pack(fill="x", padx=24, pady=(0, 12))
        for i, title in enumerate(("本局苹果", "历史最佳 · 当前难度", "成长等级")):
            cards.columnconfigure(i, weight=1, uniform="card")
            card = tk.Frame(cards, bg="#f1f7f1", padx=14, pady=9)
            card.grid(row=0, column=i, sticky="ew", padx=(0 if i == 0 else 5, 0))
            tk.Label(card, text=title, font=("Arial", 10), bg="#f1f7f1", fg="#66776c").pack(anchor="w")
            tk.Label(card, textvariable=self.values[i], font=("Arial", 22, "bold"),
                     bg="#f1f7f1", fg="#2b593b").pack(anchor="w")
        self.canvas = tk.Canvas(root, width=self.COLS*self.CELL, height=self.ROWS*self.CELL,
                                bg=self.BG, highlightthickness=1, highlightbackground="#d6e3d6")
        self.canvas.pack(padx=24)
        self.canvas.bind("<Button-1>", self.canvas_click)
        self.status = tk.StringVar()
        tk.Label(root, textvariable=self.status, bg=self.BG, fg="#587362",
                 font=("Arial", 10)).pack(pady=(8, 5))
        controls = tk.Frame(root, bg=self.BG)
        controls.pack(fill="x", padx=24, pady=(3, 9))
        tk.Label(controls, text="难度", bg=self.BG, fg="#475b4c").pack(side="left")
        self.level_menu = ttk.Combobox(controls, textvariable=self.difficulty,
                                      values=list(self.SPEEDS), state="readonly", width=6)
        self.level_menu.pack(side="left", padx=(6, 15))
        self.level_menu.bind("<<ComboboxSelected>>", self.change_difficulty)
        self.action = ttk.Button(controls, text="开始游戏", command=self.primary_action)
        self.action.pack(side="left")
        ttk.Button(controls, text="重新开始  R", command=self.reset).pack(side="left", padx=8)
        tk.Label(controls, text="方向键 / WASD · 空格暂停", font=("Arial", 10),
                 bg=self.BG, fg="#728176").pack(side="right")
        root.bind("<KeyPress>", self.on_key)
        root.bind("<FocusOut>", self.focus_lost)
        root.protocol("WM_DELETE_WINDOW", self.close)
        self.reset(ready=True)
        self.animate()

    def read_records(self):
        try:
            data = json.loads(self.score_path.read_text())
            return {k: v for k, v in data.items() if k in self.SPEEDS and type(v) is int and v >= 0}
        except (OSError, ValueError, AttributeError):
            return {}

    def save_record(self):
        if self.score <= self.records.get(self.difficulty.get(), 0):
            return
        self.records[self.difficulty.get()] = self.score
        try:
            temp = self.score_path.with_suffix(".tmp")
            temp.write_text(json.dumps(self.records, ensure_ascii=False), encoding="utf-8")
            temp.replace(self.score_path)
        except OSError:
            self.save_failed = True

    def change_difficulty(self, event=None):
        self.reset(ready=True)
        self.canvas.focus_set()

    def reset(self, ready=False):
        if self.timer is not None:
            self.root.after_cancel(self.timer)
            self.timer = None
        self.snake = [(8, 10), (7, 10), (6, 10)]
        self.direction = self.next_direction = (1, 0)
        self.turn_pending = False
        self.score = 0
        self.paused = self.over = self.won = False
        self.ready = ready
        self.save_failed = False
        self.particles = []
        self.start_best = self.records.get(self.difficulty.get(), 0)
        self.place_food()
        self.update_ui()
        self.draw()
        self.canvas.focus_set()
        if not ready:
            self.schedule()

    def place_food(self):
        occupied = set(self.snake)
        empty = [(x, y) for y in range(self.ROWS) for x in range(self.COLS) if (x, y) not in occupied]
        self.food = random.choice(empty) if empty else None

    def schedule(self):
        base, minimum = self.SPEEDS[self.difficulty.get()]
        self.timer = self.root.after(max(minimum, base - self.score * 3), self.tick)

    def primary_action(self):
        if self.ready or self.over:
            self.reset()
        else:
            self.paused = not self.paused
            self.update_ui()
        self.canvas.focus_set()

    def canvas_click(self, event):
        self.canvas.focus_set()
        if self.ready or self.over or self.paused:
            self.primary_action()

    def focus_lost(self, event):
        # 等焦点稳定后判断是否切到了另一个应用，避免点击游戏按钮时暂停。
        self.root.after_idle(self.pause_if_unfocused)

    def pause_if_unfocused(self):
        if self.root.focus_displayof() is None and not (self.ready or self.over or self.paused):
            self.paused = True
            self.update_ui()

    def on_key(self, event):
        key = event.keysym.lower()
        if event.widget is self.level_menu and key in ("up", "down", "left", "right"):
            return
        if key == "r":
            self.reset()
            return "break"
        if key in ("space", "return"):
            self.primary_action()
            return "break"
        if key == "escape" and not (self.ready or self.over):
            self.paused = True
            self.update_ui()
        moves = {"up": (0,-1), "w": (0,-1), "down": (0,1), "s": (0,1),
                 "left": (-1,0), "a": (-1,0), "right": (1,0), "d": (1,0)}
        if key in moves and not (self.ready or self.over or self.paused or self.turn_pending):
            move = moves[key]
            if move not in (self.direction, (-self.direction[0], -self.direction[1])):
                self.next_direction, self.turn_pending = move, True
        if key in moves:
            return "break"

    def tick(self):
        self.timer = None
        if self.over or self.ready:
            return
        if not self.paused:
            self.direction = self.next_direction
            self.turn_pending = False
            x, y = self.snake[0]
            dx, dy = self.direction
            head = (x + dx, y + dy)
            eating = head == self.food
            body = self.snake if eating else self.snake[:-1]
            if not (0 <= head[0] < self.COLS and 0 <= head[1] < self.ROWS) or head in body:
                self.over = True
            else:
                self.snake.insert(0, head)
                if eating:
                    self.score += 1
                    self.save_record()
                    self.burst(head)
                    self.place_food()
                    if self.food is None:
                        self.over = self.won = True
                else:
                    self.snake.pop()
            self.update_ui()
        if not self.over:
            self.schedule()

    def burst(self, cell):
        now = time.monotonic()
        for i in range(12):
            angle = i * math.tau / 12
            self.particles.append(((cell[0]+.5)*self.CELL, (cell[1]+.5)*self.CELL,
                                   math.cos(angle)*35, math.sin(angle)*35, now, i))

    def update_ui(self):
        self.values[0].set(f"{self.score:02d}")
        self.values[1].set(f"{self.records.get(self.difficulty.get(), 0):02d}")
        self.values[2].set(f"LV. {1 + self.score // 5}")
        self.action.configure(text="开始游戏" if self.ready else "再来一局" if self.over
                              else "继续游戏" if self.paused else "暂停游戏")
        self.status.set("选择难度，然后出发吧" if self.ready else
                        "最高分暂未写入磁盘，本次运行仍会保留" if self.save_failed else
                        "休息一下，果园等你回来" if self.paused else
                        f"本局收获 {self.score} 个苹果 · 点击棋盘再来一局" if self.over else
                        f"{self.difficulty.get()}模式  ·  再吃 {5-self.score%5} 个苹果升一级  ·  切换难度会开始新局")

    def animate(self):
        self.draw()
        self.frame_timer = self.root.after(33, self.animate)

    def draw(self):
        cv, c = self.canvas, self.CELL
        cv.delete("all")
        now = time.monotonic()
        width, height = self.COLS*c, self.ROWS*c
        for x in range(c, width, c):
            cv.create_line(x, 0, x, height, fill="#f1f5f0")
        for y in range(c, height, c):
            cv.create_line(0, y, width, y, fill="#f1f5f0")
        if self.food:
            fx, fy = ((v+.5)*c for v in self.food)
            pulse = 14 + math.sin(now*3)*2
            cv.create_oval(fx-pulse, fy-pulse, fx+pulse, fy+pulse, fill="#fff3e9", outline="")
            cv.create_oval(fx-8, fy+7, fx+9, fy+11, fill="#e8dfd4", outline="")
            cv.create_image(fx, fy-1+math.sin(now*3), image=self.apple)
        points = [v for x,y in self.snake for v in ((x+.5)*c, (y+.5)*c)]
        cv.create_line(*[v+2 for v in points], fill="#dee6d9", width=c-1,
                       capstyle=tk.ROUND, joinstyle=tk.ROUND)
        cv.create_line(*points, fill="#486629", width=c-5, capstyle=tk.ROUND, joinstyle=tk.ROUND)
        for x,y in reversed(self.snake):
            cv.create_image((x+.5)*c, (y+.5)*c, image=self.body_texture)
        hx,hy = ((v+.5)*c for v in self.snake[0])
        dx,dy = self.direction
        # 短舌随前进方向转动。
        if not (self.over or self.paused or self.ready) and math.sin(now*5) > .4:
            tx,ty = hx+dx*15, hy+dy*15
            cv.create_line(hx+dx*10, hy+dy*10, tx, ty, fill="#c96469", width=2)
            for side in (-1,1):
                cv.create_line(tx,ty,tx+dx*3-dy*side*2,ty+dy*3+dx*side*2,fill="#c96469")
        for side in (-1,1):
            ex,ey = hx+dx*5-dy*side*6,hy+dy*5+dx*side*6
            cv.create_oval(ex-2.8,ey-2.8,ex+2.8,ey+2.8,fill="#e3bc54",outline="#354322")
            cv.create_oval(ex-1,ey-1.8,ex+1,ey+1.8,fill="#101510",outline="")
            cv.create_oval(ex-.8,ey-1.6,ex,ey-.8,fill="white",outline="")
        self.particles = [p for p in self.particles if now-p[4] < .65]
        for x,y,vx,vy,born,i in self.particles:
            age = now-born
            px,py = x+vx*age,y+vy*age+25*age*age
            radius = 3*(1-age/.65)
            cv.create_oval(px-radius,py-radius,px+radius,py+radius,
                           fill=("#efaf51", "#83ad62", "#ed8d73")[i%3],outline="")
        if self.ready or self.paused or self.over:
            self.draw_overlay(width, height)

    def draw_overlay(self, width, height):
        cv = self.canvas
        x,y = width/2,height/2
        cv.create_rectangle(x-216,y-110,x+220,y+114,fill="#e5ece1",outline="")
        cv.create_rectangle(x-220,y-114,x+216,y+110,fill="#fcfefa",outline="#d1dfca")
        cv.create_text(x,y-76,text="S N A K E   G A R D E N",fill="#849878",font=("Arial",10))
        title = "欢迎来到青蛇果园" if self.ready else "果园小憩" if self.paused else "果园大丰收！" if self.won else "这次收获，也很不错"
        cv.create_text(x,y-37,text=title,fill="#2d5039",font=("Arial",23,"bold"))
        detail = "吃苹果，慢慢长大；记得避开墙壁和自己。" if self.ready else "准备好了，就继续你的收获。" if self.paused else f"收获 {self.score} 个苹果   /   成长等级 {1+self.score//5}"
        cv.create_text(x,y+3,text=detail,fill="#6d806c",font=("Arial",12))
        hint = "点击这里 / 按空格开始" if self.ready else "点击这里 / 按空格继续" if self.paused else "点击这里 / 按 R 再来一局"
        cv.create_rectangle(x-135,y+35,x+135,y+76,fill="#365f41",outline="")
        cv.create_text(x,y+55,text=hint,fill="white",font=("Arial",12,"bold"))
        if self.over and self.score > self.start_best:
            cv.create_text(x,y+94,text="刷新了当前难度的最高纪录！",fill="#a17831",font=("Arial",10))

    def close(self):
        for timer in (self.timer,self.frame_timer):
            if timer is not None:
                self.root.after_cancel(timer)
        self.root.destroy()

    def load_textures(self):
        self.apple = tk.PhotoImage(master=self.root, data=ASSET_DATA["apple"])
        self.apple = self.apple.zoom(3).subsample(4)
        source = tk.PhotoImage(master=self.root, data=ASSET_DATA["skin"])
        self.body_texture = tk.PhotoImage(master=self.root, width=self.CELL,
                                          height=self.CELL)
        # 将蛇皮纹理映射到圆形蛇身，并用横向光照表现体积。
        c = self.CELL
        for y in range(c):
            for x in range(c):
                nx, ny = (x + 0.5 - c / 2) / (c / 2), (y + 0.5 - c / 2) / (c / 2)
                if nx * nx + ny * ny > 0.96:
                    continue
                r, g, b = source.get(x * 4, y * 4)
                grain = (r + g + b) / 765
                light = (0.55 + 0.45 * (1 - nx * nx - ny * ny) ** 0.5)
                value = (0.48 + 0.52 * grain) * light
                color = '#%02x%02x%02x' % (int(126 * value), int(169 * value), int(61 * value))
                self.body_texture.put(color, (x, y))


if __name__ == "__main__":
    window = tk.Tk()
    SnakeGame(window)
    window.mainloop()
